"""Encoding and mojibake detection."""

from __future__ import annotations

import fnmatch
import re
import unicodedata
from bisect import bisect_right
from pathlib import Path

from issuekit.encoding.report import code_point, code_point_context, code_point_text

ENCODING_ARTIFACT_PATTERN = re.compile(
    "[\u0080-\u009f]|[\ue000-\uf8ff]|\u7e67|\u7e3a|\u8b41|\u8373|\u8389|\u87b3|\u8703|\u8708|\u8711|\u90e2|\u9622|\u9ae2|\ufffd"
)
# Generated by UTF-8 -> CP932 decoding of U+3041-U+3096, U+30A1-U+30FA, and U+4E00-U+9FA0.
# The full derived set is enabled; issuekit#229 reverted an earlier exclusion of four mojibake characters.
CP932_DOUBLE_ENCODING_LEAD_CHARACTER_PATTERN = re.compile(
    "\u6248|\u6ff6|\u7e5d|\u8375|\u83a0|\u83a8|\u83eb|\u83f4|\u8413|\u86db|\u86df|\u86ef|\u86f9|\u86fb|\u8700|\u8706|\u8709|\u870a|\u870d|\u8712|\u871a|\u8725|\u8729|\u8734|\u8737|\u873b|\u873f|\u874c|\u874e|\u8753|\u8757|\u8759|\u875f|\u8760|\u8763|\u8768|\u876a|\u876e|\u8774|\u8778|\u8782|\u879f|\u87a2|\u87ab|\u87af|\u87bb|\u87bd|\u87c0|\u87c4|\u87c6|\u87c7|\u87cb|\u87d0|\u87d2|\u87e0|\u87ef|\u87f2|\u87f6|\u87f7|\u87fe|\u8805|\u880d|\u880e|\u880f|\u8811|\u8815|\u8816|\u8822|\u894d|\u8adb|\u8ade|\u8ae0|\u8ae1|\u8ae2|\u8ae4|\u8af1|\u8af7|\u8b07|\u8b0c|\u8b10|\u8b14|\u8b16|\u8b17|\u8b1a|\u8b20|\u8b26|\u8b28|\u8b2b|\u8b33|\u8b3e|\u8b49|\u8b4c|\u8b4e|\u8b4f|\u8b56|\u8b5a|\u8b5b|\u8b5f|\u8b6b|\u8b6c|\u8b6f|\u8b74|\u8b7d|\u8b80|\u8b8c|\u8b8e|\u8b92|\u8b93|\u8b96|\u8b99|\u8b9a|\u8c3a|\u8c3f|\u8c41|\u8c48|\u8c4c|\u8c4e|\u8c50|\u8c55|\u8c62|\u8c6c|\u8c78|\u8c7a|\u8c7c|\u8c82|\u8c85|\u8c89|\u8c8a|\u8c8d|\u8c8e|\u8c94|\u8f62|\u8f63|\u8f64|\u8f9c|\u8f9f|\u8fa3|\u8fad|\u8faf|\u8fb7|\u8fda|\u8fe2|\u8fe5|\u8fea|\u8fef|\u8ff4|\u8ff8|\u8ff9|\u8ffa|\u9005|\u900b|\u900d|\u900e|\u9011|\u9015|\u9016|\u901e|\u9021|\u9027|\u9035|\u9036|\u9039|\u903e|\u9049|\u904f|\u9050|\u9051|\u9052|\u9056|\u9058|\u905e|\u9068|\u906f|\u9072|\u9076|\u907d|\u9080|\u9081|\u9082|\u9087|\u9089|\u908a|\u908f|\u90a8|\u90af|\u90b1|\u90b5|\u90db|\u90e4|\u9102|\u9112|\u9119|\u95a0|\u95a7|\u95a8|\u95ad|\u95b9|\u95bb|\u95bc|\u95be|\u95c3|\u95ca|\u95cc|\u95cd|\u95d4|\u95d5|\u95d6|\u95dc|\u95e1|\u95e2|\u95e5|\u9621|\u9628|\u962e|\u962f|\u9642|\u964b|\u964c|\u964f|\u965c|\u965d|\u965e|\u965f|\u9666|\u966c|\u9672|\u9677|\u968d|\u9695|\u9697|\u9698|\u96a7|\u96a8|\u96aa|\u96b0|\u96b1|\u96b2|\u96b4|\u96b6|\u96b8|\u96b9|\u96c9|\u96cb|\u96cd|\u96ce|\u96d5|\u96d6|\u96dc|\u96f9|\u9704|\u9706|\u9708|\u970d|\u970e|\u9711|\u9713|\u97ab|\u9a3e|\u9a4d|\u9a55|\u9a57|\u9a5b|\u9a5f|\u9a62|\u9a64|\u9a65|\u9a69|\u9a6a|\u9a6b|\u9aad|\u9ab0|\u9abc|\u9ac0|\u9acf|\u9ad1|\u9ad3|\u9ad4|\u9ade|\u9adf|\u9ae3|\u9ae6|\u9aeb|\u9aee|\u9aef|\u9af1|\u9af4|\u9af7|\u9afb|\u9b06|\u9b18|\u9b1a|\u9b1f|\u9b22|\u9b23|\u9b25|\u9b27|\u9b28|\u9b29|\u9b2a|\u9b2e|\u9b2f|\u9b32|\u9b43|\u9b44|\u9b4d|\u9b4e|\u9b4f|\u9b51|\u9b58|\u9b74|\u9b83|\u9b91|\u9b93|\u9b96|\u9b97|\u9b9f|\u9ba0|\u9ba8|\u9bb4"
)
HALFWIDTH_KATAKANA_PATTERN = re.compile("[\uff61-\uff9f]")
NON_ASCII_PATTERN = re.compile(r"[^\x00-\x7F]")


def find_encoding_artifacts(
    text: str, *, include_halfwidth_katakana: bool = True
) -> list[tuple[int, str]]:
    patterns = [
        ENCODING_ARTIFACT_PATTERN,
        CP932_DOUBLE_ENCODING_LEAD_CHARACTER_PATTERN,
    ]
    if include_halfwidth_katakana:
        patterns.append(HALFWIDTH_KATAKANA_PATTERN)
    matches = {
        match.start(): match.group()
        for pattern in patterns
        for match in pattern.finditer(text)
    }
    return sorted(matches.items())


def newline_offsets(text: str) -> tuple[int, ...]:
    offsets: list[int] = []
    offset = text.find("\n")
    while offset != -1:
        offsets.append(offset)
        offset = text.find("\n", offset + 1)
    return tuple(offsets)


def line_number_at(offsets: tuple[int, ...], index: int) -> int:
    return bisect_right(offsets, index) + 1


def is_encoding_excluded_path(file: str, patterns: tuple[str, ...]) -> bool:
    path = Path(file).as_posix()
    return any(_matches_path_pattern(path, pattern) for pattern in patterns)


def _matches_path_pattern(path: str, pattern: str) -> bool:
    return _matches_path_parts(
        path.split("/"),
        pattern.replace("\\", "/").split("/"),
    )


def _matches_path_parts(path_parts: list[str], pattern_parts: list[str]) -> bool:
    if not pattern_parts:
        return not path_parts
    pattern_part = pattern_parts[0]
    if pattern_part == "**":
        return any(
            _matches_path_parts(path_parts[index:], pattern_parts[1:])
            for index in range(len(path_parts) + 1)
        )
    if not path_parts or not fnmatch.fnmatchcase(path_parts[0], pattern_part):
        return False
    return _matches_path_parts(path_parts[1:], pattern_parts[1:])


# Reverse confirmation operates on a contiguous non-ASCII window, not an
# individual character: CP932 mojibake comes from one UTF-8 byte sequence, and
# the surrounding run supplies bytes that may complete it. C1 controls and PUA
# characters bypass the plausibility check because they are never legitimate
# source text. Strict UTF-8-as-CP932 decoding round trips losslessly, but real
# lossy corruption exists: mine-py fixture text has an unrecoverable mangled
# prefix, so callers must retain unconfirmed candidates for human review.
def confirmed_mojibake_hits(
    file: str,
    text: str,
    artifacts: list[tuple[int, str]],
    *,
    offsets: tuple[int, ...] | None = None,
) -> tuple[list[dict[str, int | str]], list[dict[str, int | str]]]:
    confirmed_hits: list[dict[str, int | str]] = []
    unconfirmed_hits: list[dict[str, int | str]] = []
    checked_windows: set[tuple[int, int]] = set()
    offsets = offsets if offsets is not None else newline_offsets(text)
    for index, character in artifacts:
        start, end = _non_ascii_window(text, index)
        if (start, end) in checked_windows:
            continue
        checked_windows.add((start, end))
        window = text[start:end]
        recovered = _reverse_cp932(window)
        hit = _mojibake_hit(file, text, index, character, offsets)
        if recovered is not None and (
            _contains_c1_control_or_private_use_character(window)
            or _is_plausible_recovery(recovered)
        ):
            hit["recovered"] = code_point_text(recovered)
            confirmed_hits.append(hit)
        else:
            unconfirmed_hits.append(hit)
    return confirmed_hits, unconfirmed_hits


def _mojibake_hit(
    file: str,
    text: str,
    index: int,
    character: str,
    offsets: tuple[int, ...],
) -> dict[str, int | str]:
    line = line_number_at(offsets, index)
    previous_newline = offsets[line - 2] if line > 1 else -1
    column = index - previous_newline
    return {
        "file": file,
        "line": line,
        "column": column,
        "code_point": code_point(character),
        "context": code_point_context(text, index, character),
    }


def _non_ascii_window(text: str, index: int) -> tuple[int, int]:
    start = index
    while start > 0 and text[start - 1] != "\n" and ord(text[start - 1]) > 0x7F:
        start -= 1
    end = index + 1
    while end < len(text) and text[end] != "\n" and ord(text[end]) > 0x7F:
        end += 1
    return start, end


def _reverse_cp932(text: str) -> str | None:
    try:
        return text.encode("cp932").decode("utf-8")
    except UnicodeError:
        return None


def _is_plausible_recovery(text: str) -> bool:
    return not any(
        character.isascii() and character.isalnum() for character in text
    )


def _contains_c1_control_or_private_use_character(text: str) -> bool:
    return any(
        0x80 <= ord(character) <= 0x9F
        or 0xE000 <= ord(character) <= 0xF8FF
        or 0xF0000 <= ord(character) <= 0xFFFFD
        or 0x100000 <= ord(character) <= 0x10FFFD
        for character in text
    )


def has_non_ascii(text: str) -> bool:
    return bool(NON_ASCII_PATTERN.search(text))


_ASCII_PUNCTUATION_TRANSLATION = str.maketrans(
    {
        "\u2010": "-",
        "\u2011": "-",
        "\u2012": "-",
        "\u2013": "-",
        "\u2014": "-",
        "\u2015": "-",
        "\u2018": "'",
        "\u2019": "'",
        "\u201a": "'",
        "\u201b": "'",
        "\u201c": '"',
        "\u201d": '"',
        "\u201e": '"',
        "\u201f": '"',
        "\u2026": "...",
        "\u2212": "-",
    }
)


def sanitize_to_ascii(text: str) -> str:
    """Fold compatible text to ASCII and drop characters that cannot be folded."""

    if not has_non_ascii(text):
        return text
    normalized = unicodedata.normalize(
        "NFKD",
        text.translate(_ASCII_PUNCTUATION_TRANSLATION),
    )
    return normalized.encode("ascii", errors="ignore").decode("ascii")


# Appended to ASCII-only rejection messages so agents can self-correct the
# common culprits instead of guessing what tripped the check.
ASCII_ONLY_HINT = "Replace em dashes, curly quotes, and non-English text."
